/// R64: Questions and answers, in English and Arabic. Keep answers short and
/// true to how the app works today (update when features change).
class FaqEntry {
  const FaqEntry(this.topicEn, this.topicAr, this.qEn, this.qAr, this.aEn, this.aAr);
  final String topicEn, topicAr, qEn, qAr, aEn, aAr;
  String topic(bool ar) => ar ? topicAr : topicEn;
  String q(bool ar) => ar ? qAr : qEn;
  String a(bool ar) => ar ? aAr : aEn;
}

const _start = ('Getting started', 'البداية');
const _privacy = ('Privacy and safety', 'الخصوصية والأمان');
const _daily = ('Everyday use', 'الاستخدام اليومي');
const _alerts = ('Reminders and notifications', 'التذكيرات والإشعارات');
const _account = ('Account and data', 'الحساب والبيانات');
const _signin = ('Signing in', 'تسجيل الدخول');

final faqEntries = <FaqEntry>[
  FaqEntry(_start.$1, _start.$2,
    'What is OneSpace?', 'ما هو OneSpace؟',
    'Your own private space and assistant: your calendar, to-do lists, reminders, notes, trips, occasions and memories, gathered from different apps into one place. Use it on your own, or invite your partner and add letters, check-ins and little gestures — whether you live together or far apart.',
    'مساحتك الخاصة ومساعدك: تقويمك وقوائم مهامك وتذكيراتك وملاحظاتك ورحلاتك ومناسباتك وذكرياتك، مجموعة من تطبيقات مختلفة في مكان واحد. استخدمه بمفردك، أو ادعُ شريكك وأضيفا الرسائل والتواصل اليومي واللفتات الصغيرة — سواء كنتما تعيشان معًا أو بعيدين.'),
  FaqEntry(_start.$1, _start.$2,
    'Can I use OneSpace without a partner?', 'هل يمكنني استخدام OneSpace دون شريك؟',
    'Yes. Married, in a relationship or not, OneSpace works fully on your own. When someone special comes along, you can invite them; until then everything stays yours.',
    'نعم. متزوجًا كنت أو في علاقة أو لا، يعمل OneSpace بالكامل وأنت بمفردك. وعندما يظهر شخص مميز يمكنك دعوته؛ وحتى ذلك الحين يبقى كل شيء لك.'),
  FaqEntry(_start.$1, _start.$2,
    'How do I connect my partner?', 'كيف أربط شريكي؟',
    'From Today, choose Invite my partner and enter their email address. Only the account with that verified email can accept. The invitation expires after 48 hours. Your partner can open the invitation in OneSpace or use its code or QR code, then accept it. Your personal content remains private.',
    'من «اليوم»، اختر «دعوة شريكي» وأدخل بريده الإلكتروني. لا يمكن قبول الدعوة إلا من الحساب المرتبط بذلك البريد بعد تأكيده. تنتهي صلاحية الدعوة بعد 48 ساعة. يمكن لشريكك فتح الدعوة داخل OneSpace أو استخدام رمزها أو رمز QR ثم قبولها. يبقى محتواك الشخصي خاصًا بك.'),
  FaqEntry(_start.$1, _start.$2,
    'What are the five tabs?', 'ما هي التبويبات الخمسة؟',
    'Today shows what needs you now. Remember holds the calendar, to-do lists, reminders and notes. Coordinate has Activities (plans and decisions) and Trips. Connect is for letters, daily connection, gestures, memories and experiences. Me is your profile, settings and help.',
    '«اليوم» يعرض ما يحتاجك الآن. «تذكّر» فيه التقويم وقوائم المهام والتذكيرات والملاحظات. «تنسيق» فيه الأنشطة (الخطط والقرارات) والرحلات. «تواصل» للرسائل والتواصل اليومي واللفتات والذكريات والتجارب. «أنا» لملفك الشخصي وإعداداتك والمساعدة.'),
  FaqEntry(_privacy.$1, _privacy.$2,
    'Who can see what I add?', 'من يمكنه رؤية ما أضيفه؟',
    'Only you, and the partner you invite — never anyone else. Each item shows "Shared" or "Only me" at the bottom of its page. "Only me" items, drafts and private reminders are visible only to you, never to a current or future partner.',
    'أنت والشريك الذي تدعوه فقط — ولا أحد غيركما. يظهر في أسفل صفحة كل عنصر «مشترك» أو «أنا فقط». العناصر الخاصة والمسودات والتذكيرات الخاصة تظهر لك وحدك.'),
  FaqEntry(_privacy.$1, _privacy.$2,
    'Can I plan a surprise?', 'هل يمكنني التخطيط لمفاجأة؟',
    'Yes. Make the occasion, gift idea or note "Only me". Your partner will not see it or get any notification about it until you choose to share.',
    'نعم. اجعل المناسبة أو فكرة الهدية أو الملاحظة «أنا فقط». لن يراها شريكك ولن يصله أي إشعار عنها حتى تقرر مشاركتها.'),
  FaqEntry(_privacy.$1, _privacy.$2,
    'Does OneSpace track my location or phone?', 'هل يتتبع OneSpace موقعي أو هاتفي؟',
    'No. There is no location tracking, no activity tracking and no "online" status. For weather you choose a city yourself. Photos and documents stay private: only you, or you and your partner if you share them.',
    'لا. لا يوجد تتبع للموقع ولا للنشاط ولا حالة «متصل». للطقس تختار المدينة بنفسك. الصور والمستندات تبقى خاصة: لك وحدك، أو لك ولشريكك إن شاركتها.'),
  FaqEntry(_privacy.$1, _privacy.$2,
    'Can I lock the app?', 'هل يمكنني قفل التطبيق؟',
    'Yes. OneSpace can ask for your phone PIN, fingerprint or Face ID when it opens.',
    'نعم. يمكن أن يطلب OneSpace رمز الهاتف أو البصمة أو بصمة الوجه عند فتحه.'),
  FaqEntry(_daily.$1, _daily.$2,
    'Where did something I removed go?', 'أين ذهب شيء حذفته؟',
    'For features that offer a Removed filter, you can find and restore individually removed items there. This does not apply to permanent shared-space or account deletion: those records and attachments cannot be restored.',
    'في المزايا التي تحتوي على فلتر «المحذوفة»، يمكنك العثور على العناصر المحذوفة بشكل فردي واستعادتها. لا ينطبق ذلك على الحذف النهائي للمساحة المشتركة أو الحساب؛ فلا يمكن استعادة تلك السجلات ومرفقاتها.'),
  FaqEntry(_daily.$1, _daily.$2,
    'How do I save something from another app?', 'كيف أحفظ شيئًا من تطبيق آخر؟',
    'On Android, use Share in any app and choose OneSpace. It lands in "Items to sort" (⋮ at the top) where you turn it into a note, to-do, trip item or memory. Sharing into OneSpace on iPhone is coming.',
    'على أندرويد، استخدم «مشاركة» في أي تطبيق واختر OneSpace. يصل إلى «عناصر للفرز» (⋮ بالأعلى) حيث تحوّله إلى ملاحظة أو مهمة أو عنصر رحلة أو ذكرى. المشاركة إلى OneSpace على iPhone قادمة.'),
  FaqEntry(_daily.$1, _daily.$2,
    'How do I change the language?', 'كيف أغيّر اللغة؟',
    'Me → Language and currency. Each of you can select English or Arabic independently. App labels and standard messages follow that setting; content you write is not automatically translated.',
    '«أنا» ← «اللغة والعملة». يمكن لكل منكما اختيار الإنجليزية أو العربية بشكل مستقل. تتبع تسميات التطبيق ورسائله الأساسية هذا الاختيار، أما المحتوى الذي تكتبه فلا يُترجم تلقائيًا.'),
  FaqEntry(_daily.$1, _daily.$2,
    'Can I change the colors and background?', 'هل يمكنني تغيير الألوان والخلفية؟',
    'Yes. Me → Settings → Appearance & themes: choose a color theme, light or dark, and a seasonal background (or let it follow the date).',
    'نعم. «أنا» ← «الإعدادات» ← «المظهر»: اختر لون السمة والوضع الفاتح أو الداكن وخلفية موسمية (أو اجعلها تتبع التاريخ).'),
  FaqEntry(_alerts.$1, _alerts.$2,
    'I am not getting notifications.', 'لا تصلني الإشعارات.',
